{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Replacing § 49-10-1403(e), the bill requires a participating student's parent to ensure annual administration of all TCAP tests, or state-board-authorized successor tests, administered to public school students in the same grade or course subject, subject to the alternate-assessment exemption.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "Shall ensure that the participating student is annually\n\n administered all Tennessee comprehensive assessment program (TCAP)\n\n tests"
    },
    {
      "id": "P2",
      "proposition": "A parent of a participating student in grade eleven must ensure administration of the examination administered to public school eleventh graders pursuant to § 49-6-6001(b)(1), subject to the alternate-assessment exemption.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "In grade eleven (11) shall ensure that the student is\n\n administered the examination that is administered to public school\n\n students in grade eleven (11) pursuant to § 49-6-6001(b)(1);"
    },
    {
      "id": "P3",
      "proposition": "A parent of a participating student in kindergarten through grade three must ensure annual administration of each of the three Tennessee universal reading screeners, or state-board-approved universal reading screeners described in § 49-1-905(c), during each of the three department-established administration windows under § 49-1-905(c)(1), subject to the alternate-assessment exemption.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "shall\n\n ensure that the participating student is annually administered each of the\n\n three (3) Tennessee universal reading screeners"
    },
    {
      "id": "P4",
      "proposition": "Results of a participating student's tests administered under the replacement § 49-10-1403(e) must be reported to the student's parent.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "A participating student's results on the tests administered pursuant to\n\n this subsection (e) must be reported to the parent of the student."
    },
    {
      "id": "P5",
      "proposition": "Students with disabilities who would have participated in the alternate assessment, as determined on their IEP, are exempt from the requirements of the replacement § 49-10-1403(e).",
      "importance": "supporting",
      "section": "SECTION 1",
      "source_quote": "Students with disabilities who would have participated in the alternate\n\n assessment, as determined on the student's IEP, are exempt from the\n\n requirements in this subsection (e)."
    },
    {
      "id": "P6",
      "proposition": "New § 49-10-1404(d) requires a participating school to publish on its website lesson plans, a syllabus, and academic standards for each class offered, plus a current list of materials in its library collection.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "A participating school shall publish the school's lesson plans and\n\n syllabus for each class offered by the school, a current list of materials in the\n\n school's library collection, and the academic standards for each class offered by\n\n the school on the school's website."
    },
    {
      "id": "P7",
      "proposition": "For the website-publication requirement in new § 49-10-1404(d), the library collection includes materials made available to students, including course-curriculum materials. Materials means books, periodicals, newspapers, manuscripts, films, prints, documents, microfilm, discs, cassettes, videotapes, video games, applications, and subscription content in any form.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "\"Library collection\" means the materials made available to\n\n students by the participating school, including materials made available to\n\n students as part of a course curriculum;"
    },
    {
      "id": "P8",
      "proposition": "New § 49-10-1404(e) requires a participating school to ensure that all its educators hold a valid state-board-issued license to teach in a public school.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "A participating school shall ensure that all educators of the participating\n\n school hold a valid license to teach in a public school that is issued by the state board of\n\n education."
    },
    {
      "id": "P9",
      "proposition": "New § 49-6-2607(e)(6) requires a participating school to publish on its website lesson plans, a syllabus, and academic standards for each class offered, plus a current list of materials in its library collection.",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "Publish the school's lesson plans and syllabus for each class offered\n\n by the school, a current list of materials in the school's library collection, and the\n\n academic standards for each class offered by the school on the school's website;"
    },
    {
      "id": "P10",
      "proposition": "For the website-publication requirement in new § 49-6-2607(e)(6), the library collection includes materials made available to students, including course-curriculum materials. Materials means books, periodicals, newspapers, manuscripts, films, prints, documents, microfilm, discs, cassettes, videotapes, video games, applications, and subscription content in any form.",
      "importance": "supporting",
      "section": "SECTION 3",
      "source_quote": "\"Library collection\" means the materials made available to\n\n students by the participating school, including materials made available to\n\n students as part of a course curriculum;"
    },
    {
      "id": "P11",
      "proposition": "New § 49-6-2607(e)(7) requires a participating school to ensure that all its educators hold a valid state-board-issued license to teach in a public school.",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "Ensure that all educators of the participating school hold a valid license to\n\n teach in a public school that is issued by the state board of education."
    },
    {
      "id": "P12",
      "proposition": "Replacing § 49-6-2606(a)(1), the bill makes annual administration of the TCAP tests, or state-board-authorized successor tests, administered to public school students in the same grade or course subject a condition of a student's participation in the program.",
      "importance": "core",
      "section": "SECTION 4",
      "source_quote": "Participating students must be annually administered the Tennessee\n\n comprehensive assessment program (TCAP) tests, or successor tests authorized\n\n by the state board of education"
    },
    {
      "id": "P13",
      "proposition": "Under the replacement § 49-6-2606(a)(1), participating students in grade eleven must, as a condition of program participation, be administered the examination administered to public school eleventh graders pursuant to § 49-6-6001(b)(1).",
      "importance": "core",
      "section": "SECTION 4",
      "source_quote": "Participating students in grade eleven (11) must be administered the\n\n examination that is administered to public schools students in grade eleven (11)\n\n pursuant to § 49-6-6001(b)(1);"
    },
    {
      "id": "P14",
      "proposition": "Under the replacement § 49-6-2606(a)(1), participating students in kindergarten through grade three must, as a condition of program participation, annually receive each of the three Tennessee universal reading screeners, or state-board-approved universal reading screeners described in § 49-1-905(c), during each of the three department-established administration windows under § 49-1-905(c)(1).",
      "importance": "core",
      "section": "SECTION 4",
      "source_quote": "Participating students in kindergarten through grade three (K-3) must\n\n annually be administered each of the three (3) Tennessee universal reading\n\n screeners"
    },
    {
      "id": "P15",
      "proposition": "The act takes effect July 1, 2025.",
      "importance": "supporting",
      "section": "SECTION 5",
      "source_quote": "This act takes effect July 1, 2025, the public welfare requiring it."
    }
  ]
}

